import sys

def main():
    s = sys.stdin.readline()
    groups = [1]
    op = 1
    out = []
    after_star = False
    for c in s:
        if c.isspace():
            continue
        if c == '(':
            groups.append(groups[-1] * op)
            op = 1
        elif c == ')':
            groups.pop()
        elif c == '+':
            op = 1
        elif c == '-':
            op = -1
        elif c == '*':
            out.append('*')
            after_star = True
        else:
            if after_star:
                out.append(c)
                after_star = False
            else:
                sign = groups[-1] * op
                if sign == -1:
                    out.append('-' + c)
                elif out:
                    out.append('+' + c)
                else:
                    out.append(c)
    print(''.join(out))

