            L += 2 * k - 1
            while depth > 0 and rng.random() < pc:
                out.append(')')
                depth -= 1
                L += 1
            if L >= target:
                out.append(')' * depth)
                break
            out.append(rng.choice('+-'))
            L += 1
        return ''.join(out)
